fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut max_len = 1;
    let mut current_len = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            current_len += 1;
        } else {
            // streak broke, record and reset
            max_len = max_len.max(current_len);
            current_len = 1;
        }
    }

    // in case the longest streak goes up to the last element
    max_len.max(current_len)
}

